RE_HEX = re.compile(r'^\s*([A-Za-z]+)\s*=\s*0x([0-9a-fA-F]+)\s*$', re.M)
RE_DEC = re.compile(r'^\s*e\s*=\s*([0-9]+)\s*$', re.M)

def fetch(url: str, timeout: int = _sage_const_10 ) -> str:
    req = urllib.request.Request(url, headers={"User-Agent": "sage-solve/1.0"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode("utf-8", errors="replace")

def parse_instance(text: str):
    d = {}
    for k, v in RE_HEX.findall(text):
        d[k] = int(v, _sage_const_16 )
    m = RE_DEC.search(text)
    if m:
        d["e"] = int(m.group(_sage_const_1 ))
    needed = ["N", "A", "c", "k", "e"]
    missing = [x for x in needed if x not in d]
    if missing:
        raise ValueError(f"Missing fields: {missing}")
    return d

def factor_known_highbits(N: Integer, A: Integer, k: int):
    # assume q = (A << k) + x, 0 <= x < 2^k
    qbar = A << k

    R = PolynomialRing(Zmod(N), names=("x",))
    x = R.gen()

    # try both signs just in case instance defines q = qbar - x
    candidates = [
        ("plus", x + qbar),
        ("minus", qbar - x),
    ]

    for name, f in candidates:
        # try a few parameter tweaks for robustness
        for beta in [_sage_const_0p50 , _sage_const_0p49 , _sage_const_0p51 ]:
            for Xpow in [k, k + _sage_const_1 ]:
                X = Integer(_sage_const_1 ) << Xpow
                roots = f.small_roots(X=X, beta=beta)
                if not roots:
                    continue

                for r in roots:
                    r = Integer(r)
                    # derive q candidates from root
                    qcands = [qbar + r, qbar - r]
                    for qc in qcands:
                        g = gcd(N, qc)
                        if _sage_const_1  < g < N:
                            q = Integer(g)
                            p = Integer(N // q)
                            return p, q, {"poly": name, "beta": beta, "X": Xpow, "root": int(r)}
    raise ValueError("Failed to factor (no valid gcd from Coppersmith roots)")

def rsa_decrypt(N, e, p, q, c):
    phi = (p - _sage_const_1 ) * (q - _sage_const_1 )
    d = inverse_mod(Integer(e), phi)
    m = power_mod(Integer(c), d, Integer(N))
    pt = long_to_bytes(int(m))
    return int(m), pt

def extract_flag(pt: bytes):
    # heuristic: tìm token giống flag
    # (chỉnh regex tuỳ CTF)
    m = re.search(rb"[A-Za-z0-9]{0,20}\{[^{}]{5,200}\}", pt)
    if m:
        return m.group(_sage_const_0 )
    # fallback: chuỗi ascii dài
    m = re.search(rb"[ -~]{10,}", pt)
    return m.group(_sage_const_0 ) if m else pt

def solve_url(url: str, verbose: bool = True):
    txt = fetch(url)
    inst = parse_instance(txt)

    N = Integer(inst["N"])
    A = Integer(inst["A"])
    c = Integer(inst["c"])
    k = int(inst["k"])
    e = int(inst["e"])

    if verbose:
        print(f"[+] fetched {url}")
        print(f"[+] bitlen(N)={N.nbits()}  k={k}  bitlen(A)={Integer(A).nbits()}")

