    if verbose:
        print("[+] factored!")
        print("[+] meta:", meta)
        print("[+] p =", p)
        print("[+] q =", q)

    m_int, pt = rsa_decrypt(N, e, p, q, c)

    print("[+] plaintext(raw) =", pt)
    try:
        print("[+] plaintext(utf8) =", pt.decode())
    except Exception:
        pass
    print("[+] extracted =", extract_flag(pt))

